svg.script:

// In een echte situatie zou de iframe een apart HTML-bestand zijn geladen via een <iframe> tag.
// Omdat dit in een enkele SVG draait, simuleren we het iframe-mechanisme via window.postMessage naar zichzelf/subframes.

window.addEventListener("message", function(event) {
  // Controleer data afkomstig van cross-frame berichten
  if (event.data.sender === "parent") {
    document.getElementById('iframeLog').textContent = "Ontvangen van ouder: " + event.data.text;
  } else if (event.data.sender === "iframe") {
    document.getElementById('parentLog').textContent = "Ontvangen van iframe: " + event.data.text;
  }
});

function sendToIframe() {
  const val = document.getElementById('parentInput').value;
  if(val.trim() !== "") {
    // Verstuur bericht (in een echte webpagina doe je dit via iframeEl.contentWindow.postMessage(...))
    window.postMessage({ sender: "parent", text: val }, "*");
    document.getElementById('parentInput').value = "";
  }
}

function sendToParent() {
  const val = document.getElementById('iframeInput').value;
  if(val.trim() !== "") {
    // Verstuur bericht terug naar de parent (in een echte iframe doe je dit via window.parent.postMessage(...))
    window.postMessage({ sender: "iframe", text: val }, "*");
    document.getElementById('iframeInput').value = "";
  }
}
